                    else:
                        print(f"  file: {e}")
            else:
                print(f"{path}: not found")
    except Exception as ex:
        print(f"{path}: error - {ex}")

# Search more broadly for task/demo data files
import os
import glob

# Search all directories under the runs folder
runs_path = "/home/USER/runs/paper/qwen-h0c1-card/frozen/seen-reference"

def search_for_files(path, max_depth=3):
    """Search recursively for relevant files"""
    results = []

    def recurse(d, depth):
        if depth > max_depth:
            return
        try:
            entries = sorted(os.listdir(d))[:10]
        except:
            return
        for e in entries:
            ep = os.path.join(d, e)
            info = os.stat(ep)
            if os.path.isfile(ep):
                size = info.st_size
                if size > 100:  # Skip small files
                    results.append((ep, 'file', size))
            elif os.path.isdir(ep):
                recurse(ep, depth + 1)

    recurse(path, 0)
    return results[:50]

results = search_for_files(runs_path)
for f, t, s in results:
    print(f"{f}: {t} ({s})")

